import '../core/permission_kind.dart';
import 'scan_result.dart';

/// Renders `lib/play_permission_setup.g.dart`.
String generateDartSource(
  ScanResult result, {
  Set<PermissionKind> required = const {},
  Set<PermissionKind> exclude = const {},
}) {
  final b = StringBuffer()
    ..writeln(
      '// GENERATED by `dart run play_permission_setup generate` – DO NOT EDIT.',
    )
    ..writeln(
      '// Re-run after changing AndroidManifest.xml / Info.plist / Podfile.',
    )
    ..writeln('// ignore_for_file: type=lint')
    ..writeln()
    ..writeln("import 'package:play_permission_setup/play_permission_setup.dart';")
    ..writeln()
    ..writeln(
      '/// Permissions found in your platform files. Each item only applies',
    )
    ..writeln('/// on the platforms where it is actually declared.')
    ..writeln('const List<PermissionItem> kDetectedPermissions = [');

  for (final kind in PermissionKind.values) {
    if (exclude.contains(kind)) continue;
    final platforms = result.declared[kind];
    if (platforms == null || platforms.isEmpty) continue;
    final sorted = platforms.toList()..sort((a, b) => a.index - b.index);
    b
      ..writeln('  PermissionItem(')
      ..writeln('    kind: PermissionKind.${kind.name},')
      ..writeln('    isRequired: ${required.contains(kind)},')
      ..writeln(
        '    platforms: {${sorted.map((p) => 'PermissionPlatform.${p.name}').join(', ')}},',
      )
      ..writeln('  ),');
  }
  b.writeln('];');
  return b.toString();
}
